// Generic company mailboxes (ir@, info@ ...) are shared routes, not a named person's inbox.
const ROLE_ROUTE=/^(ir|info|investorrelations|investor\.relations|presse|press|community|development|taiwan|poland\.bd|contact|enquiries|office|support)@/i;
/** Partners in the same shape the contact store and contact UI use for projects. */
export const partnerProjects=partnerRecords.map(p=>({id:p.id,name:p.company,contacts:(partnerContacts[p.id]||[]).map(c=>({name:c.name,title:c.title,role:c.role,email:c.email||'',linkedin:c.linkedin||'',phones:c.phone?[c.phone]:[],status:c.verification||'Published in prior research · not verified',source:c.source||'',association:ROLE_ROUTE.test(c.email||'')?'shared':'unconfirmed'}))}));
export const partnerRegistry=Object.freeze({
 count: partnerProjects.length,
 ids: Object.freeze(partnerProjects.map(p=>p.id)),
 key: partnerProjects.map(p=>p.id).join('|')
});
